 printf 'B300_GRAND_STAGEH_OK=%q\n' "$STAGEH_OK"; printf 'B300_GRAND_STAGEH_MIN_SPEEDUP=%q\n' "$STAGEH_MIN_SPEEDUP"; printf 'B300_GRAND_STAGEH_SELF_EVICT=%q\n' "$STAGEH_SELF_EVICT"; printf 'B300_GRAND_STAGEH_WIDTH=%q\n' "${B300_STAGEH_PREPARED_WIDTH:-0}"; printf 'B300_GRAND_STAGEH_DISTANCE=%q\n' "${B300_STAGEH_PREPARED_DISTANCE:-0}"; printf 'B300_GRAND_STAGEH_MANIFEST=%q\n' "${B300_STAGEH_PREPARED_MANIFEST:-}"
 printf 'B300_GRAND_HYBRID8_NEXTSELF_SEARCH_WIDTHS=%q\n' "$HYBRID_NS_WIDTH_LIST"; printf 'B300_GRAND_HYBRID8_NEXTSELF_SEARCH_DISTANCES=%q\n' "$HYBRID_NS_DISTANCE_LIST"; printf 'B300_GRAND_HYBRID8_NEXTSELF_WIDTH=%q\n' "${B300_HYBRID8_NEXTSELF_PREPARED_WIDTH:-0}"; printf 'B300_GRAND_HYBRID8_NEXTSELF_DISTANCE=%q\n' "${B300_HYBRID8_NEXTSELF_PREPARED_DISTANCE:-0}"; printf 'B300_GRAND_HYBRID8_NEXTSELF_MANIFEST=%q\n' "${B300_HYBRID8_NEXTSELF_PREPARED_MANIFEST:-}"
 printf 'B300_GRAND_PRIMARY_BIN=%q\n' "$P_BIN"; printf 'B300_GRAND_PRIMARY_LABEL=%q\n' "$P_LABEL"; printf 'B300_GRAND_PRIMARY_THREADS=%q\n' "$P_THREADS"; printf 'B300_GRAND_BASE_BIN=%q\n' "$B_BIN"; printf 'B300_GRAND_BASE_LABEL=%q\n' "$B_LABEL"; printf 'B300_GRAND_BASE_THREADS=%q\n' "$B_THREADS"; printf 'B300_GRAND_EXTRA_BIN=%q\n' "$E1_BIN"; printf 'B300_GRAND_EXTRA_LABEL=%q\n' "$E1_LABEL"; printf 'B300_GRAND_EXTRA_THREADS=%q\n' "$E1_THREADS"; printf 'B300_GRAND_EXTRA2_BIN=%q\n' "$E2_BIN"; printf 'B300_GRAND_EXTRA2_LABEL=%q\n' "$E2_LABEL"; printf 'B300_GRAND_EXTRA2_THREADS=%q\n' "$E2_THREADS"; printf 'B300_GRAND_EXTRA3_BIN=%q\n' "$E3_BIN"; printf 'B300_GRAND_EXTRA3_LABEL=%q\n' "$E3_LABEL"; printf 'B300_GRAND_EXTRA3_THREADS=%q\n' "$E3_THREADS"
 printf 'B300_GRAND_DROPPED_JOINT_BASE_WHEN_BOTH=%q\n' "$DROP_JOINT_BASE"; printf 'B300_GRAND_DROPPED_NEXTSELF_CONTROL_WHEN_COMPOSED=%q\n' "$DROP_NEXTSELF_CONTROL"; printf 'B300_GRAND_PROFILE_FILE=%q\n' "$PROFILE_FILE"; printf 'B300_GRAND_SMOKE_PRIME=%q\n' "$PRIME"; printf 'B300_GRAND_TARGET_MIB=%q\n' "$TARGET_MIB"; printf 'B300_GRAND_MAX_WINDOW=%q\n' "$MAX_WINDOW"
} >"$SUMMARY_ENV"
